/** Comments: the comments of the row on the page */
function PostCommentsSection({ id, user }: { id: ReturnType<typeof idOf>; user: SessionUser | null }) {
  const [page, setPage] = useState(1);
  const [formKey, setFormKey] = useState(0);
  const queryClient = useQueryClient();
  const navigate = useNavigate();
  const opens = user !== null && (user as { role?: unknown }).role === "admin";
  const input = { page, page_size: 10, article_id: id } as Inputs["comments"]["list"];
  const list = useQuery({ queryKey: ["comments", "list", input], queryFn: () => client.comments.list(input) });
  const createRow = useMutation({
    mutationFn: (input: Inputs["comments"]["create"]) => client.comments.create(input),
    onSuccess: async () => {
      setFormKey(current => current + 1);
      await queryClient.invalidateQueries({ queryKey: ["comments"] });
    }
  });
  const status = errorStatus(list.error);
  if (status === 401 || status === 403) return null;
  return (
    <section className="mt-8 space-y-3">
      <h2 className="text-sm font-semibold">
        {"Comments"}
        {list.data ? <span className="ml-2 font-normal text-muted-foreground">{list.data.page.total}</span> : null}
      </h2>
      {list.isPending ? (
        <ListSkeleton />
      ) : list.error ? (
        <ErrorNote error={list.error} />
      ) : list.data.data.length === 0 ? (
        <p className="text-sm text-muted-foreground">No comments yet.</p>
      ) : (
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Body</TableHead>
              <TableHead>Author</TableHead>
              <TableHead>Created At</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {list.data.data.map((row) => (
              <TableRow key={text(row.id)} className={opens ? "cursor-pointer" : undefined} onClick={opens ? () => navigate({ to: "/moderation/$id", params: { id: text(row.id) } }) : undefined}>
                <TableCell>{text(row.body)}</TableCell>
                <TableCell>{<Link to="/authors/$id" params={{ id: text(row.author_id) }} className="hover:underline" onClick={event => event.stopPropagation()}>{(row.author ? text(row.author.name) : text(row.author_id))}</Link>}</TableCell>
                <TableCell>{formatDateTime(row.created_at)}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}
      {list.data ? <Pagination page={page} pageSize={10} total={list.data.page.total} onChange={setPage} /> : null}
      {canCreatePostComments(user) ? (
        <PostCommentsForm
          key={formKey}
          fields={POSTCOMMENTS_CREATE}
          initial={EMPTY_POSTCOMMENTS}
          submitLabel="Add"
          pending={createRow.isPending}
          error={createRow.error}
          onSubmit={values => createRow.mutate({ ...toPostCommentsCreateInput(values), article_id: id } as Inputs["comments"]["create"])}
        />
      ) : null}
    </section>
  );
}

function PostPageInner() {
  const { id: rawId } = useParams({ from: "/posts/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.posts.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["posts"]["update"]) => client.posts.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["posts"]["delete"]) => client.posts.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/posts" });
    }
  });
  const publishAction = useMutation({
    mutationFn: (input: Inputs["posts"]["publish"]) => client.posts.publish(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const lockAction = useMutation({
    mutationFn: (input: Inputs["posts"]["lock"]) => client.posts.lock(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const unlockAction = useMutation({
    mutationFn: (input: Inputs["posts"]["unlock"]) => client.posts.unlock(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <RowError error={query.error} signIn={<Link to="/login" className={buttonVariants()}>Sign in</Link>} />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.title) || "Article " + text(row.id)}
      actions={
        <>
          {canPublish(user, row) ? (
            <Button variant="outline" size="sm" disabled={publishAction.isPending} onClick={() => publishAction.mutate({ id })}>
              Publish
            </Button>
          ) : null}
          {canLock(user, row) ? (
            <Button variant="outline" size="sm" disabled={lockAction.isPending} onClick={() => lockAction.mutate({ id })}>
              Lock
            </Button>
          ) : null}
          {canUnlock(user, row) ? (
            <Button variant="outline" size="sm" disabled={unlockAction.isPending} onClick={() => unlockAction.mutate({ id })}>
              Unlock
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this article?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={publishAction.error} className="mb-4" />
      <ErrorNote error={lockAction.error} className="mb-4" />
      <ErrorNote error={unlockAction.error} className="mb-4" />
      {editing ? (
        <PostForm
          fields={POST_UPDATE}
          initial={postFromRow(row)}
          current={row}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toPostUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Content">
          <p className="whitespace-pre-wrap">{text(row.content) || "—"}</p>
        </FieldRow>
        <FieldRow label="Published">{row.published == null ? "—" : <Badge variant={row.published ? "default" : "outline"}>{yesNo(row.published)}</Badge>}</FieldRow>
        <FieldRow label="Locked">{row.locked == null ? "—" : <Badge variant={row.locked ? "default" : "outline"}>{yesNo(row.locked)}</Badge>}</FieldRow>
        <FieldRow label="Cover">
          <FilePreview file={row.cover} />
        </FieldRow>
        <FieldRow label="Tags">
          <span className="flex flex-wrap gap-1">
            {(row.tags ?? []).map(item => (
              <Badge key={text(item)} variant="secondary">
                {text(item)}
              </Badge>
            ))}
          </span>
        </FieldRow>
        <FieldRow label="Posted At">{formatDateTime(row.posted_at) || "—"}</FieldRow>
        <FieldRow label="Author">{<Link to="/authors/$id" params={{ id: text(row.author_id) }} className="hover:underline">{(row.author ? text(row.author.name) : text(row.author_id)) || "—"}</Link>}</FieldRow>
        </dl>
      )}
      <PostCommentsSection key={text(row.id)} id={id} user={user} />
    </Pane>
  );
}

export const PostPage = guarded(PostPageInner);
